import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Form, Row } from 'antd'
import { isEmpty } from 'lodash'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import { showNotification } from '../../../../../../components/ShowNotification'
import AddressChanges from '../../../components/AddressChanges'
import { useAddBranch } from '../../state/hooks/useProviderState'
import { BranchFormStyle } from './index.style'
import get from 'lodash/get'
import PropTypes from 'prop-types'
import LocationPicker from '../../../components/LocationPicker'

function BranchForm (props) {
  const { defaultValues = {}, extraDetails } = props
  const addressSubmit = useRef('')

  const [, addBranchRequest] = useAddBranch()

  const [latLng, setLatLng] = useState({
    lat: get(defaultValues, 'location.latitude', ''),
    lng: get(defaultValues, 'location.longitude', '')
  })

  const handleLatLngChange = useCallback((newLatLng) => {
    setLatLng(newLatLng)
  }, [])

  const [{ ADD_BRANCH_ERROR, addBranchStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (addBranchStatus === 'success') {
      if (!isEmpty(defaultValues)) {
        showNotification('success', 'Branch successfully Edited')
      } else {
        showNotification('success', 'A new Branch is successfully added')
      }

      dispatchError(resetError({
        addBranchStatus: ''
      }))
      props.onCloseBranchForm()
    } else if (ADD_BRANCH_ERROR && addBranchStatus) {
      showNotification('error', addBranchStatus)
      dispatchError(resetError({
        addBranchStatus: ''
      }))
    }
  }, [addBranchStatus, ADD_BRANCH_ERROR, defaultValues, dispatchError, props])

  const extraDetailItems = useCallback((item) => {
    return {
      name: item.name,
      title: item.name,
      subTitle: item.name,
      type: 'text',
      min: item.min_length,
      max: item.max_length,
      defaultValue: get(defaultValues?.extra_details, [item.name], ''),
      ...(item.required ? {} : { required: false })
    }
  }, [defaultValues?.extra_details])

  const extraDetailForm = useCallback((extraDetails) => {
    const forms = []
    if (!extraDetails) { return [] } else {
      extraDetails.map((item) => (
        forms.push(extraDetailItems(item))
      ))
      return forms
    }
  }, [extraDetailItems])

  const extraDetailObj = useCallback((extraDetails, value) => {
    const data = {}
    if (!extraDetails) { return {} } else {
      extraDetails.forEach((item) => (
        data[item.name] = value[item.name]
      ))
      return data
    }
  }, [])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    props.form.validateFields(async (err, values) => {
      if (!err) {
        const addrData = await addressSubmit.current()
        const extraData = extraDetailObj(extraDetails, values)
        if (!isEmpty(addrData)) {
          addBranchRequest({
            branchCode: defaultValues?.code,
            providerCode: props.providerCode,
            body: {
              code: defaultValues?.code,
              location: {
                ...addrData,
                latitude: latLng.lat ? latLng.lat : null,
                longitude: latLng.lng ? latLng.lng : null
              },
              ...(extraDetails ? { extra_details: { ...extraData } } : {}),
              ...values
            }
          })
        }
      }
    })
  }, [props.providerCode, defaultValues,
    props.form, addBranchRequest, latLng, extraDetailObj, extraDetails
  ])

  const renderFormItems = useCallback((item) => {
    // wrapping utitily function with class function to pass common parameters
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: props.form.getFieldDecorator,
      getFieldValue: props.form.getFieldValue
    })
  }, [props.form])

  const renderForm = useCallback((formData) => {
    return (
      formData.map((item, index) => (
        renderFormItems(item)
      ))
    )
  }, [renderFormItems])

  const handleGetSubmitMethods = useCallback((method) => {
    addressSubmit.current = method
  }, [])

  const defaultAddr = useMemo(() => {
    let addr = get(defaultValues, 'location', {})
    if (addr === null) {
      addr = {}
    }
    return addr
  }, [defaultValues])

  return (
    <BranchFormStyle>
      <Form onSubmit={handleSubmit}>
        {
          renderForm([
            {
              name: 'name',
              title: 'Name',
              subTitle: 'name',
              type: 'text',
              defaultValue: get(defaultValues, 'name', ''),
              max: 80,
              min: 3
            },
            {
              name: 'email',
              title: 'Email',
              subTitle: 'email',
              type: 'email',
              defaultValue: get(defaultValues, 'email', ''),
              required: false,
              max: 240
            },
            {
              name: 'claims_email',
              title: 'Email for Claims',
              subTitle: 'claims_email',
              type: 'email',
              defaultValue: get(defaultValues, 'claims_email', ''),
              required: false,
              max: 240
            },
            {
              name: 'claims_contact_no',
              title: 'Contact Number for Claims',
              subTitle: 'claims_contact_no',
              type: 'number',
              defaultValue: get(defaultValues, 'claims_contact_no', ''),
              required: false
              // max: 14
            },
            ...extraDetailForm(extraDetails)
          ])
        }
        <AddressChanges
          address={defaultAddr}
          onGetSubmitMethod={handleGetSubmitMethods}
          fullWidth
        />
        <p className='label'> Select Location: </p>
        <LocationPicker latLng={latLng} onLatLngChange={handleLatLngChange} />
        <Row justify='end' type='flex' className='form-submit-btn'>
          <Button type='primary' htmlType='submit'>
            Submit
          </Button>
        </Row>
      </Form>
    </BranchFormStyle>
  )
}

BranchForm.propTypes = {
  defaultValues: PropTypes.object,
  onCloseBranchForm: PropTypes.func,
  onGetBranchesRequest: PropTypes.func,
  providerCode: PropTypes.string
}

const wrapperBranchForm = Form.create()(BranchForm)

export default wrapperBranchForm
