import CircularLoader from '../../../../../../../components/CircularLoader'
import { ProviderDetailStyle } from './index.style'
import { Button } from 'antd'
import { useCallback, useEffect, useMemo } from 'react'
import ProviderInfo from '../components/ProviderInfo'
import ProviderUsers from '../components/ProviderUsers'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useGetBranchList, useGetIncomingCommissionConfigList, useGetProviderDetail, useGetQuotationDetailList } from '../../../state/hooks/useProviderState'
import ProviderBranches from '../components/ProviderBranches'
import { showNotification } from '../../../../../../../components/ShowNotification'
import PresetListContainer from '../../../../../Preset/pages/PresetListContainer'
import IncomingCommission from '../components/IncomingCommission'
import isVNPath from '../../../../../../../helpers/isVNPath'
import ProviderQuotationInfo from '../components/ProviderQuotationInfo'

function ProviderDetail (props) {
  const [{ getBranchListData = {} }, getBranchListRequest] = useGetBranchList()
  const [{ getProviderDetailData = {} }, getProviderDetailRequest] = useGetProviderDetail()
  const [{ getIncomingCommissionConfigListData = [] }, getIncomingCommissionConfigListRequest] = useGetIncomingCommissionConfigList()
  const [{ getQuotationDetailListData = {} }, getQuotationDetailRequest] = useGetQuotationDetailList()
  const { providerCode } = useMemo(() => props.match.params, [props.match.params])

  const [{ GET_BRANCH_LIST_LOADER, GET_PROVIDER_DETAIL_LOADER }
  ] = useLoaderContextValue()

  const [{ GET_BRANCH_LIST_ERROR, GET_PROVIDER_DETAIL_ERROR, getBranchListStatus, getProviderDetailStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (getBranchListStatus && GET_BRANCH_LIST_ERROR) {
      showNotification('error', getBranchListStatus)
      dispatchError(resetError({
        getBranchListStatus: ''
      }))
    }
    if (getProviderDetailStatus && GET_PROVIDER_DETAIL_ERROR) {
      showNotification('error', getProviderDetailStatus)
      dispatchError(resetError({
        getProviderDetailStatus: ''
      }))
    }
  }, [getBranchListStatus, getProviderDetailStatus,
    GET_BRANCH_LIST_ERROR, GET_PROVIDER_DETAIL_ERROR,
    dispatchError
  ])

  useEffect(() => {
    getBranchListRequest({
      providerCode,
      query: {
        is_active: [true, false]
      }
    })
    if (!isVNPath()) {
      getIncomingCommissionConfigListRequest({
        query: {
          provider: providerCode
        }
      })
    }
    getProviderDetailRequest({
      providerCode
    })
    getQuotationDetailRequest({
      query: {
        agent_provider: providerCode
      }
    })
  }, [providerCode, getBranchListRequest,
    getProviderDetailRequest, getIncomingCommissionConfigListRequest,
    getQuotationDetailRequest
  ])

  const handleGoBack = useCallback(() => {
    props.history.goBack()
  }, [props.history])

  return (
    <ProviderDetailStyle>
      <CircularLoader isSpining={GET_BRANCH_LIST_LOADER || GET_PROVIDER_DETAIL_LOADER}>
        <Button
          className='mb-10'
          type='primary'
          htmlType='submit'
          onClick={handleGoBack}
        >
          Back
        </Button>
        <ProviderInfo providerInfo={getProviderDetailData} onGetProviderDetail={getProviderDetailRequest} />
        {
          process.env.REACT_APP_IS_PRESET_ENABLED === 'true' && !isVNPath() &&
            <PresetListContainer providerCode={providerCode} />
        }
        <ProviderUsers providerCode={providerCode} branches={getBranchListData} />
        {
          process.env.REACT_APP_IS_INCOMING_COMMISSION_ENABLED === 'true' && !isVNPath() &&
            <IncomingCommission
              providerData={getProviderDetailData}
              getIncomingCommissionConfigListData={getIncomingCommissionConfigListData}
            />
        }
        <ProviderQuotationInfo
          providerCode={providerCode}
          getQuotationDetailListData={getQuotationDetailListData}
          getQuotationDetailRequest={getQuotationDetailRequest}
        />
        <ProviderBranches
          providerCode={providerCode}
          getBranchListData={getBranchListData}
          onGetBranchesRequest={getBranchListRequest}
          getProviderDetailData={getProviderDetailData}
        />
      </CircularLoader>
    </ProviderDetailStyle>
  )
}

export default ProviderDetail
