import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Form, Row } from 'antd'
import { isEmpty } from 'lodash'
import { useCallback, useEffect } from 'react'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import { showNotification } from '../../../../../../components/ShowNotification'
import { useAddQuotationDetail, useGetProductList } from '../../state/hooks/useProviderState'
import { QuotationInfoFormStyle } from './index.style'
import get from 'lodash/get'
import PropTypes from 'prop-types'
import { confirmationOptionsData } from '../../constants'

function QuotationInfoForm (props) {
  const { form, defaultValues = {}, isEditMode, providerCode, fetchQuotationList, onCloseBranchForm, updateQuotationDetailRequest } = props

  const [{ getProductListData = [] }, getProductListRequest] = useGetProductList()
  const [, addQuotationDetailRequest] = useAddQuotationDetail()

  const [{ ADD_QUOTATION_DETAIL_ERROR, addQuotationDetailStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    getProductListRequest()
  }, [getProductListRequest])

  useEffect(() => {
    if (addQuotationDetailStatus === 'success') {
      if (!isEmpty(defaultValues)) {
        showNotification('success', 'Quotation successfully Edited')
      } else {
        showNotification('success', 'A new Quotation is successfully added')
      }

      dispatchError(resetError({
        addQuotationDetailStatus: ''
      }))
      fetchQuotationList()
      onCloseBranchForm()
    } else if (ADD_QUOTATION_DETAIL_ERROR && addQuotationDetailStatus) {
      showNotification('error', addQuotationDetailStatus)
      dispatchError(resetError({
        addQuotationDetailStatus: ''
      }))
    }
  }, [defaultValues, dispatchError, addQuotationDetailStatus, ADD_QUOTATION_DETAIL_ERROR, onCloseBranchForm, fetchQuotationList])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    form.validateFields(async (err, values) => {
      if (!err) {
        if (isEditMode && defaultValues?.id) {
          updateQuotationDetailRequest({
            reference_id: defaultValues?.reference_id,
            body: {
              ...values,
              quotation_slip_pic: values.quotation_slip_pic === 'Yes',
              closing_slip_pic: values.closing_slip_pic === 'Yes',
              send_email: values.send_email === 'Yes',
              agent_provider: providerCode,
              id: defaultValues?.id
            }
          })
        } else {
          addQuotationDetailRequest({
            body: {
              ...values,
              quotation_slip_pic: values.quotation_slip_pic === 'Yes',
              closing_slip_pic: values.closing_slip_pic === 'Yes',
              send_email: values.send_email === 'Yes',
              agent_provider: providerCode
            }
          })
        }
      }
    })
  }, [form, isEditMode, defaultValues, updateQuotationDetailRequest, providerCode, addQuotationDetailRequest])

  const renderFormItems = useCallback((item) => {
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: form.getFieldDecorator,
      getFieldValue: form.getFieldValue
    })
  }, [form])

  const renderForm = useCallback((formData) => {
    return (
      formData.map((item) => (
        renderFormItems(item)
      ))
    )
  }, [renderFormItems])

  return (
    <QuotationInfoFormStyle>
      <Form onSubmit={handleSubmit}>
        {
          renderForm([
            {
              name: 'name',
              title: 'Name',
              subTitle: 'name',
              type: 'text',
              defaultValue: get(defaultValues, 'name', ''),
              max: 80,
              min: 3
            },
            {
              name: 'product',
              title: 'Product Name',
              placeholder: 'Select Product',
              required: true,
              type: 'search',
              defaultValue: get(defaultValues, 'product', ''),
              data: getProductListData
            },
            {
              name: 'email',
              title: 'Email',
              subTitle: 'email',
              type: 'email',
              defaultValue: get(defaultValues, 'email', ''),
              max: 240
            },
            {
              name: 'quotation_slip_pic',
              title: 'Quotation Slip PIC',
              required: true,
              type: 'search',
              defaultValue: defaultValues.quotation_slip_pic ? 'Yes' : 'No',
              data: confirmationOptionsData
            },
            {
              name: 'closing_slip_pic',
              title: 'Closing Slip PIC',
              required: true,
              type: 'search',
              defaultValue: defaultValues.closing_slip_pic ? 'Yes' : 'No',
              data: confirmationOptionsData
            },
            {
              name: 'send_email',
              title: 'Send Email',
              required: true,
              type: 'search',
              defaultValue: defaultValues.send_email ? 'Yes' : 'No',
              data: confirmationOptionsData
            }
          ])
        }
        <Row justify='end' type='flex' className='form-submit-btn'>
          <Button type='secondary' className='cancel-button' onClick={onCloseBranchForm}>
            Cancel
          </Button>
          <Button type='primary' htmlType='submit'>
            Submit
          </Button>
        </Row>
      </Form>
    </QuotationInfoFormStyle>
  )
}

QuotationInfoForm.propTypes = {
  defaultValues: PropTypes.object,
  onCloseBranchForm: PropTypes.func
}

const wrapperQuotationInfoForm = Form.create()(QuotationInfoForm)

export default wrapperQuotationInfoForm
