import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Col, Form, Row } from 'antd'
import { isEmpty } from 'lodash'
import { useCallback, useEffect, useState } from 'react'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import { showNotification } from '../../../../../../components/ShowNotification'
import { IncomingCommissionFormStyle } from './index.style'
import get from 'lodash/get'
import PropTypes from 'prop-types'
import { useAddIncomingCommissionConfig, useGetProductList, useIndependentPackageList, useUpdateIncomingCommissionConfig } from '../../state/hooks/useProviderState'
import moment from 'moment-timezone'
import TieringInputFields from '../TieringInputFields'
import CircularLoader from '../../../../../../components/CircularLoader'
import set from 'lodash/set'
import { tieringCombinationOptions, tieringSelectOptions } from '../../constants'

function IncomingCommissionForm (props) {
  const {
    defaultValues = {},
    form,
    isEditFormDisabled,
    disableFields
  } = props
  const disabledDate = form.getFieldValue('validity_start_date')

  const [extraCommissionType, setExtraCommissionType] = useState(get(defaultValues, 'agreement_type', 'FLAT'))
  const [isReview, setIsReview] = useState(false)
  const [formValues, setFormValues] = useState()
  const [tieringFormValues, setTieringFormValues] = useState()
  const [isEditMode, setIsEditMode] = useState(false)
  const { getFieldValue, resetFields } = form
  const productType = getFieldValue('product')

  const [{ getProductListData = [] }, getProductListRequest] = useGetProductList()
  const [, addIncomingCommissionRequest] = useAddIncomingCommissionConfig()
  const [, updateIncomingCommissionRequest] = useUpdateIncomingCommissionConfig()
  const [{ getIndependentPackageListData = [] }, getIndependentPackageListRequest] = useIndependentPackageList()

  const [{ ADD_INCOMING_COMMISSION_LOADER, UPDATE_INCOMING_COMMISSION_LOADER }
  ] = useLoaderContextValue()

  const [{
    ADD_INCOMING_COMMISSION_CONFIG_ERROR, UPDATE_INCOMING_COMMISSION_CONFIG_ERROR,
    addIncomingCommissionConfigStatus, updateIncomingCommissionConfigStatus,
    addIncomingCommissionConfigErrorData, updateIncomingCommissionConfigErrorData
  },
  dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (!isEmpty(defaultValues)) {
      setFormValues(defaultValues)
      setIsEditMode(true)
      if (get(defaultValues, 'agreement_type') !== 'FLAT') {
        setTieringFormValues(get(defaultValues, 'extra_commission', ''))
      }
    }
  }, [defaultValues])

  useEffect(() => {
    if (productType) {
      resetFields(['package'])
      getIndependentPackageListRequest({
        productCode: productType
      })
    }
  }, [productType, getIndependentPackageListRequest, resetFields])

  useEffect(() => {
    getProductListRequest()
    if (isEditFormDisabled) {
      setIsReview(true)
    }
  }, [getProductListRequest, isEditFormDisabled])

  useEffect(() => {
    if (addIncomingCommissionConfigStatus === 'success' ||
    updateIncomingCommissionConfigStatus === 'success') {
      if (isEditMode) {
        showNotification('success', 'Incoming Commission Config successfully Edited')
      } else {
        showNotification('success', 'A new Incoming Commission Config is successfully added')
      }

      dispatchError(resetError({
        addIncomingCommissionConfigStatus: '',
        updateIncomingCommissionConfigStatus: ''
      }))
      props.onCloseIncomingCommissionForm()
      setTimeout(() => {
        window.location.reload()
      }, 1000)
    } else if (ADD_INCOMING_COMMISSION_CONFIG_ERROR && addIncomingCommissionConfigStatus) {
      showNotification('error', addIncomingCommissionConfigErrorData.message)
      dispatchError(resetError({
        addIncomingCommissionConfigStatus: ''
      }))
    } else if (UPDATE_INCOMING_COMMISSION_CONFIG_ERROR && updateIncomingCommissionConfigStatus) {
      showNotification('error', updateIncomingCommissionConfigErrorData.message)
      dispatchError(resetError({
        updateIncomingCommissionConfigStatus: ''
      }))
    }
  }, [addIncomingCommissionConfigStatus, ADD_INCOMING_COMMISSION_CONFIG_ERROR,
    updateIncomingCommissionConfigStatus, UPDATE_INCOMING_COMMISSION_CONFIG_ERROR,
    addIncomingCommissionConfigErrorData, updateIncomingCommissionConfigErrorData,
    formValues, dispatchError, props, isEditMode])

  const handleEdit = useCallback(() => {
    if (isReview) {
      setIsReview(false)
    } else {
      props.onCloseIncomingCommissionForm()
    }
  }, [isReview, props])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    if (!isReview) {
      form.validateFields((err, values) => {
        if (err) {
          return
        }
        setIsReview(() => true)
        if (extraCommissionType !== 'FLAT') {
          values.extra_commission = tieringFormValues
        }
        setFormValues(values)
      })
    } else {
      const finalData = {
        ...formValues,
        package: formValues.package ? formValues.package : '*',
        provider: props?.providerData?.code,
        extra_commission: extraCommissionType === 'FLAT' ? formValues.extra_commission : tieringFormValues,
        validity_start_date: moment(formValues.validity_start_date).format('YYYY-MM-DD'),
        validity_end_date: moment(formValues.validity_end_date).format('YYYY-MM-DD')
      }
      if (tieringFormValues && extraCommissionType === 'MONTHLY') {
        finalData.agreement_type = ([...tieringSelectOptions, ...tieringCombinationOptions].filter((data) =>
          data.source_type === tieringFormValues[0]?.rules[0]?.source_type)[0].agreement_type)
      }
      if (isEditMode) {
        updateIncomingCommissionRequest({
          id: get(defaultValues, 'id'),
          body: {
            ...finalData
          }
        })
      } else {
        addIncomingCommissionRequest({
          body: { ...finalData }
        })
      }
    }
  }, [isReview, formValues, form, extraCommissionType, isEditMode, defaultValues, props?.providerData?.code,
    tieringFormValues, addIncomingCommissionRequest, updateIncomingCommissionRequest])

  const renderFormItems = useCallback((item) => {
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: props?.form?.getFieldDecorator,
      getFieldValue: props?.form?.getFieldValue
    })
  }, [props.form])

  const renderForm = useCallback((formData) => {
    return (
      formData?.map((item, index) => (
        renderFormItems(item)
      ))
    )
  }, [renderFormItems])

  const handleDisabledDate = (current, disabledDate) => {
    if (disabledDate) {
      return current && (current < moment(disabledDate).add(-1, 'day').endOf('day'))
    }
    return false
  }
  const handleStartDataChange = useCallback(() => {
    set(formValues, 'validity_end_date', '')
    form.setFieldsValue({
      validity_end_date: ''
    })
  }, [formValues, form])

  return (
    <IncomingCommissionFormStyle>
      <CircularLoader isSpinning={ADD_INCOMING_COMMISSION_LOADER || UPDATE_INCOMING_COMMISSION_LOADER}>
        {
          isReview &&
            <div>
              <Row className='review-config'>
                <Col className='review-field-heading'>Config Name </Col>
                <Col className='review-field-value'>{get(formValues, 'config_name', '')}</Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading'>Provider Name</Col>
                <Col className='review-field-value'>{get(formValues, 'provider', '')}</Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading'>Product Name</Col>
                <Col className='review-field-value'>{get(formValues, 'product', '')}</Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading'>Package Name</Col>
                <Col className='review-field-value'>{get(formValues, 'package', '')}</Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading'>Brokerage Fee (BF)</Col>
                <Col className='review-field-value'>{get(formValues, 'commission', '')}</Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading'>Engineering Fee (EF) Type</Col>
                <Col className='review-field-value'>{extraCommissionType === 'FLAT'
                  ? get(formValues, 'agreement_type', '')
                  : ([...tieringSelectOptions, ...tieringCombinationOptions].filter((data) =>
                      data.source_type === tieringFormValues[0]?.rules[0]?.source_type)[0]?.agreement_type)}
                </Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading' />
                <Col className='review-field-value'>
                  {
                    extraCommissionType === 'FLAT'
                      ? get(formValues, 'extra_commission', '')
                      : tieringFormValues?.map((data, index) => {
                        return (
                          <div key={index}>
                            <div className='outer-row'>
                              <div className='tiering-row'>
                                {
                                data?.rules?.map((innerData, innerIndex) => {
                                  return (
                                    <div key={innerIndex} className='inner-row'>
                                      <div className='tiering-readonly-first'>{get(innerData, 'source_type', '') || 'N/A'}</div>
                                      {
                                        get(innerData, 'source_type', '') === 'Vehicle Type'
                                          ? <div className='tiering-readonly'>{innerData?.val || 'N/A'}</div>
                                          : (
                                            <>
                                              <div className='tiering-readonly'>{isEditFormDisabled ? innerData?.val?.split('-')[0] : get(innerData, 'gte', '') || 'N/A'}</div>
                                              upto
                                              <div className='tiering-readonly'>{isEditFormDisabled ? innerData?.val?.split('-')[1] : get(innerData, 'lt', '') || 'N/A'}</div>
                                            </>
                                            )
                                      }
                                    </div>
                                  )
                                })
                              }
                              </div>
                              <div className='fee'>
                                =
                                <div className='tiering-readonly'>{get(data, 'rate', '') || 'N/A'}%</div>
                              </div>
                            </div>
                            <hr />
                          </div>
                        )
                      })
                  }
                </Col>
              </Row>
              <Row className='review-config'>
                <Col className='review-field-heading'>Effective Date</Col>
                <Col className='review-field-value'>
                  {`${moment(formValues?.validity_start_date).format('DD-MM-YYYY')} 
                  upto ${moment(formValues?.validity_end_date).format('DD-MM-YYYY')}`}
                </Col>
              </Row>
            </div>
        }
        {
          !isReview &&
            <Form>
              {
                renderForm([
                  {
                    name: 'config_name',
                    title: 'Config Name',
                    subTitle: 'config_name',
                    type: 'text',
                    defaultValue: get(formValues, 'config_name', ''),
                    required: true,
                    max: 100,
                    min: 3
                  },
                  {
                    name: 'provider',
                    title: 'Provider Name',
                    subTitle: 'provider',
                    type: 'text',
                    defaultValue: props.providerData.name,
                    required: true,
                    max: 240,
                    disabled: true
                  },
                  {
                    name: 'product',
                    title: 'Product Name',
                    placeholder: 'Select Product',
                    required: true,
                    type: 'search',
                    defaultValue: get(formValues, 'product', ''),
                    data: getProductListData,
                    disabled: disableFields,
                    className: 'product-name'
                  },
                  {
                    name: 'package',
                    title: 'Package Name',
                    placeholder: 'Select Package',
                    required: getIndependentPackageListData.length !== 0,
                    type: 'search',
                    defaultValue: get(formValues, 'package', ''),
                    disabled: disableFields,
                    data: getIndependentPackageListData
                  }
                ])
              }
              <div className='brokerage-fee'>
                {
                  renderFormItems({
                    name: 'commission',
                    title: 'Brokerage Fee (BF)',
                    subTitle: 'commission',
                    type: 'number',
                    defaultValue: get(formValues, 'commission', ''),
                    required: true,
                    min: 1
                  })
                }
                <span className='percent-symbol'>%</span>
              </div>
              <div className='engineering-fee-type-field'>
                <div className='review-title'>
                  {!isReview &&
                    <span className='required-star'>*</span>}
                  <span className='date-heading'>Engineering Fee Type: </span>
                </div>
                <div className='engineering-fee-type-radio'>
                  {
                    renderFormItems({
                      name: 'agreement_type',
                      radioDataKey: 'agreement_type',
                      title: 'Engineering Fee Type',
                      subTitle: 'agreement_type',
                      type: 'hybrid_radio',
                      defaultValue: get(formValues, 'agreement_type', '') || extraCommissionType,
                      required: true,
                      isKeyDisabled: () => true,
                      isEnableType: true,
                      onlyRadio: true,
                      runtimeRequestParams: {},
                      handleRuntimeParams: (data) => {
                        setExtraCommissionType(() => (data.value))
                      },
                      data: [
                        {
                          value: 'FLAT',
                          title: 'Flat'
                        },
                        {
                          value: ['MONTHLY', 'CUSTOM'].includes(extraCommissionType) ? extraCommissionType : 'MONTHLY',
                          title: 'Tiering'
                        }
                      ]
                    })
                  }
                </div>
              </div>
              {
                extraCommissionType === 'FLAT' &&
                  <div className='engineering-flat-fee'>
                    {
                      renderFormItems({
                        name: 'extra_commission',
                        subTitle: 'extra_commission',
                        type: 'number',
                        defaultValue: get(formValues, 'extra_commission', ''),
                        required: true,
                        title: 'Extra Commission',
                        min: 1,
                        max: 999
                      })
                    }
                    <span className='percent-symbol'>%</span>
                  </div>
              }
              {
                (extraCommissionType === 'MONTHLY' || extraCommissionType === 'CUSTOM') &&
                  <TieringInputFields
                    productType={productType}
                    formValues={get(defaultValues, 'agreement_type') !== 'FLAT' ? get(formValues, 'extra_commission', '') : tieringFormValues}
                    setFormValues={setTieringFormValues}
                  />
              }
              <div className='effective-date'>
                <div className='review-title'>
                  {!isReview &&
                    <span className='required-star'>*</span>}
                  <span className='date-heading'>Effective Date :</span>
                </div>
                {
                  renderFormItems({
                    name: 'validity_start_date',
                    placeholder: 'Start Date',
                    type: 'datepicker',
                    title: 'Start Date',
                    required: true,
                    defaultValue: get(formValues, 'validity_start_date') && moment(get(formValues, 'validity_start_date')),
                    handleChangeMultiFormData: handleStartDataChange
                  })
                }
                <span className='date-seprator'>up to</span>
                <div className='validity-end-date'>
                  {
                    renderFormItems({
                      name: 'validity_end_date',
                      placeholder: 'End Date',
                      type: 'datepicker',
                      title: 'End Date',
                      required: true,
                      defaultValue: get(formValues, 'validity_end_date') && moment(get(formValues, 'validity_end_date')),
                      handleDisabledDate: handleDisabledDate,
                      disabledDate: disabledDate,
                      disabled: !disabledDate
                    })
                  }
                </div>
              </div>
            </Form>
        }
        <div className='modal-text'>
          The configuration will apply immediately for both existing and incoming policies<br />based on the effective period once form submitted.<br />The effective date is refer to the binding date.
        </div>
        {
          !isEditFormDisabled &&
            <Row justify='end' type='flex'>
              <Button type='primary' className='edit-button' htmlType='submit' onClick={handleEdit}>
                {isReview ? 'Back to Edit' : 'Cancel'}
              </Button>
              <Button type='primary' htmlType='submit' onClick={handleSubmit}>
                {isReview ? 'Submit' : 'Preview'}
              </Button>
            </Row>
        }
      </CircularLoader>
    </IncomingCommissionFormStyle>
  )
}

IncomingCommissionForm.propTypes = {
  defaultValues: PropTypes.object,
  onCloseIncomingCommissionForm: PropTypes.func
}

const wrapperIncomingCommissionForm = Form.create()(IncomingCommissionForm)

export default wrapperIncomingCommissionForm
