import { Button, Col, Modal, Row } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import LayoutContentStyle from '../../../../../../../../components/utility/layoutContent.style'
import TableWrapper from '../../../../../pagination.style'
import { QuotationListTable } from '../../../../constants'
import QuotationInfoForm from '../../../../components/QuotationInfoForm'
import PropTypes from 'prop-types'
import { useUpdateQuotationDetail } from '../../../../state/hooks/useProviderState'
import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { showNotification } from '../../../../../../../../components/ShowNotification'

function ProviderQuotationInfo (props) {
  const [showQuotationForm, setShowQuotationForm] = useState(false)
  const [showRevokeConfirmation, setShowRevokeConfirmation] = useState(false)
  const [isEditMode, setIsEditMode] = useState(false)
  const [quotationColumns, setQuotationColumns] = useState([])

  const { providerCode, getQuotationDetailListData, getQuotationDetailRequest } = props
  const [, updateQuotationDetailRequest] = useUpdateQuotationDetail()

  const [{ UPDATE_QUOTATION_DETAIL_ERROR, updateQuotationDetailStatus },
    dispatchError
  ] = useErrorContextValue()

  const [formDefaultValues, setFormDefaultValues] = useState({})

  const fetchQuotationList = useCallback((queryObject) => {
    getQuotationDetailRequest({
      query: {
        agent_provider: providerCode,
        ...queryObject,
        page_size: 10
      }
    })
  }, [getQuotationDetailRequest, providerCode])

  useEffect(() => {
    fetchQuotationList()
  }, [fetchQuotationList])

  const closeQuotationInfoForm = useCallback(() => {
    setFormDefaultValues({})
    setShowQuotationForm(false)
    setShowRevokeConfirmation(false)
  }, [])

  useEffect(() => {
    if (updateQuotationDetailStatus === 'success') {
      if (isEditMode) {
        showNotification('success', 'Quotation successfully Updated')
      } else {
        showNotification('success', 'Quotation is successfully Removed')
      }
      dispatchError(resetError({
        updateQuotationDetailStatus: ''
      }))
      fetchQuotationList()
      closeQuotationInfoForm()
    } else if (UPDATE_QUOTATION_DETAIL_ERROR && updateQuotationDetailStatus) {
      showNotification('error', updateQuotationDetailStatus)
      dispatchError(resetError({
        updateQuotationDetailStatus: ''
      }))
    }
  }, [dispatchError, updateQuotationDetailStatus, UPDATE_QUOTATION_DETAIL_ERROR, isEditMode, closeQuotationInfoForm, fetchQuotationList, showRevokeConfirmation])

  const handleAddQuotation = useCallback(() => {
    setIsEditMode(false)
    setShowQuotationForm(true)
  }, [])

  const handleAction = useCallback((useCase, data) => {
    if (useCase === 'revoke') {
      setShowRevokeConfirmation(true)
      setFormDefaultValues(data)
    } else {
      setIsEditMode(true)
      setFormDefaultValues(data)
      setShowQuotationForm(true)
    }
  }, [])

  const handleRevokeQuotation = useCallback(() => {
    updateQuotationDetailRequest({
      reference_id: formDefaultValues?.reference_id,
      body: {
        is_active: false
      }
    })
  }, [formDefaultValues?.reference_id, updateQuotationDetailRequest])

  const getQuotationListTable = useCallback(() => {
    return QuotationListTable({
      handleAction
    })
  }, [handleAction])

  useEffect(() => {
    setQuotationColumns(getQuotationListTable())
  }, [getQuotationListTable])

  return (
    <LayoutContentStyle>
      {
        showQuotationForm &&
          <Modal
            footer={null}
            visible={showQuotationForm}
            onCancel={closeQuotationInfoForm}
            className='quotation-modal'
          >
            <QuotationInfoForm
              isEditMode={isEditMode}
              defaultValues={formDefaultValues}
              providerCode={providerCode}
              fetchQuotationList={fetchQuotationList}
              updateQuotationDetailRequest={updateQuotationDetailRequest}
              onCloseBranchForm={closeQuotationInfoForm}
            />
          </Modal>
      }
      {
        showRevokeConfirmation &&
          <Modal
            okText='Submit'
            onOk={handleRevokeQuotation}
            visible={showRevokeConfirmation}
            onCancel={closeQuotationInfoForm}
          >
            Revoke Entry
          </Modal>
      }
      <Row type='flex' justify='space-between'>
        <Col>
          <h3 className='heading-blue'><b>Quotation Slip Info</b></h3>
        </Col>
        <Col>
          <Button
            className='mb-10'
            type='primary'
            htmlType='submit'
            onClick={handleAddQuotation}
          >
            Add New Config
          </Button>
        </Col>
      </Row>

      <div className='mt-10'>
        <TableWrapper
          columns={quotationColumns}
          bordered
          rowKey={record => record.id}
          dataSource={getQuotationDetailListData?.results?.length ? getQuotationDetailListData.results : []}
          pagination={{
            pageSize: 10
          }}
          className='isoSearchableTable agent-table-data'
        />
      </div>
    </LayoutContentStyle>
  )
}

ProviderQuotationInfo.propTypes = {
  providerCode: PropTypes.string,
  getIncomingCommissionConfigListData: PropTypes.object
}

export default ProviderQuotationInfo
