import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Col, Modal, Row } from 'antd'
import get from 'lodash/get'
import { useCallback, useEffect, useState } from 'react'
import { showNotification } from '../../../../../../../../components/ShowNotification'
import LayoutContentStyle from '../../../../../../../../components/utility/layoutContent.style'
import TableWrapper from '../../../../../pagination.style'
import UserForm from '../../../../components/UserForm'
import { userListTable } from '../../../../constants'
import { useAddUser, useGetUserList } from '../../../../state/hooks/useProviderState'
import PropTypes from 'prop-types'

function ProviderUsers (props) {
  const [showUserForm, setShowUserForm] = useState(false)
  const [userColumns, setUserColumns] = useState([])
  const [page, setPage] = useState(1)
  const [formDefaultValues, setFormDefaultValues] = useState({})
  const [isRevokeCase, setIsRevokeCase] = useState(false)

  const { providerCode } = props
  const [{ getUserListData = {} }, getUserListRequest] = useGetUserList()

  const [, addUserRequest] = useAddUser()
  const [{ GET_USER_LIST_LOADER }
  ] = useLoaderContextValue()

  const [{ GET_USER_LIST_ERROR, getUserListStatus, ADD_USER_ERROR, addUserStatus },
    dispatchError
  ] = useErrorContextValue()

  const closeUserForm = useCallback(() => {
    setShowUserForm(false)
  }, [])

  const handleAddUser = useCallback(() => {
    setFormDefaultValues({})
    setShowUserForm(true)
  }, [])

  const handleAction = useCallback((useCase, data) => {
    switch (useCase) {
      case 'edit':
        setFormDefaultValues(data)
        setShowUserForm(true)
        break
      case 'revoke':
        setIsRevokeCase(true)
        addUserRequest({
          id: get(data, 'reference_id', ''),
          body: {
            is_active: false
          }
        })
        break
      default:
        break
    }
  }, [addUserRequest])

  const getUserListTable = useCallback(() => {
    return userListTable({
      handleAction
    })
  }, [handleAction])

  const fetchUserList = useCallback((queryObject) => {
    getUserListRequest({
      query: {
        agent_provider: providerCode,
        ...queryObject,
        page_size: 10
      }
    })
  }, [providerCode, getUserListRequest])

  useEffect(() => {
    fetchUserList({})
  }, [fetchUserList])

  useEffect(() => {
    if (getUserListStatus && GET_USER_LIST_ERROR) {
      showNotification('error', getUserListStatus)
      dispatchError(resetError({
        getUserListStatus: ''
      }))
    } else if (getUserListStatus === 'success') {
      setUserColumns(getUserListTable())
      dispatchError(resetError({
        getUserListStatus: ''
      }))
    }
    if (addUserStatus && ADD_USER_ERROR) {
      showNotification('error', addUserStatus)
      dispatchError(resetError({
        addUserStatus: ''
      }))
    } else if (addUserStatus === 'success') {
      if (isRevokeCase) {
        showNotification('success', 'Access successfully Revoked')
        setIsRevokeCase(false)
      }
      fetchUserList()
      dispatchError(resetError({
        addUserStatus: ''
      }))
    }
  }, [getUserListStatus, addUserStatus, ADD_USER_ERROR,
    fetchUserList, GET_USER_LIST_ERROR, dispatchError,
    getUserListTable, isRevokeCase
  ])

  const handleTableChange = useCallback((pagination) => {
    const { pageSize, current } = pagination
    const finalFilter = {
      page: current,
      page_size: pageSize
    }
    setPage(current)
    fetchUserList(finalFilter)
  }, [fetchUserList])

  return (
    <LayoutContentStyle>
      {
        showUserForm &&
          <Modal
            footer={null}
            visible={showUserForm}
            onCancel={closeUserForm}
          >
            <UserForm
              defaultValues={formDefaultValues}
              onCloseUserForm={closeUserForm}
              onfetchUserList={fetchUserList}
              providerCode={providerCode}
              branches={props.branches}
            />
          </Modal>
      }
      <Row type='flex' justify='space-between'>
        <Col>
          <h3 className='heading-blue'><b>Providers Users</b></h3>
        </Col>
        <Col>
          <Button
            className='mb-10'
            type='primary'
            htmlType='submit'
            onClick={handleAddUser}
          >
            ADD User
          </Button>
        </Col>
      </Row>

      <div className='mt-10'>
        <TableWrapper
          columns={userColumns}
          bordered
          rowKey={record => record.id}
          dataSource={getUserListData?.results?.length ? getUserListData?.results : []}
          pagination={{
            pageSize: 10,
            current: page,
            total: getUserListData?.count || ''
          }}
          loading={GET_USER_LIST_LOADER}
          onChange={handleTableChange}
          className='isoSearchableTable agent-table-data'
        />
      </div>
    </LayoutContentStyle>
  )
}

ProviderUsers.propTypes = {
  branches: PropTypes.array,
  providerCode: PropTypes.string
}

export default ProviderUsers
