import { getQueryString } from '../helpers/constants'

const BASE_URL = process.env.REACT_APP_API_ENDPOINT

// data apis
export const getShortProviderListApi = `${BASE_URL}/api/agent/provider-list/?details=short`
export const getProductListApi = `${BASE_URL}/api/agent/product-list/`
export const getIndependentPackageListApi = (productCode) => `${BASE_URL}/api/agent/independent-package-list/?product_code=${productCode}`

// presetList - get | createPreset - post
export const getPresetListApi = `${BASE_URL}/api/agent/preset-list/`
export const createPresetApi = `${BASE_URL}/api/agent/create-preset/`

// presetDetails - get | updatePreset - put | deletePreset - delete
export const presetDetailsApi = (uuid) => `${BASE_URL}/api/agent/${uuid}/preset-details/`
export const updatePresetApi = (uuid) => `${BASE_URL}/api/agent/${uuid}/update-preset/`
export const deletePresetApi = (uuid) => `${BASE_URL}/api/agent/${uuid}/delete-preset/`

// routes
export const createPresetRoute = (params = {}) => {
  const queryString = getQueryString(params)
  return `/preset/create/${queryString}`
}
export const editPresetRoute = (presetId) => `/preset/${presetId}/edit`
export const viewPresetRoute = (presetId, params = {}) => {
  const queryString = getQueryString(params)
  return `/preset/${presetId}/${queryString}`
}
export const presetListRoute = `${BASE_URL}/preset/list/`
