import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Col, Modal, Row } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import { showNotification } from '../../../../../../../../components/ShowNotification'
import LayoutContentStyle from '../../../../../../../../components/utility/layoutContent.style'
import TableWrapper from '../../../../../pagination.style'
import BranchForm from '../../../../components/BranchForm'
import { branchListTable } from '../../../../constants'
import { useAddBranch } from '../../../../state/hooks/useProviderState'
import PropTypes from 'prop-types'

function ProviderBranches (props) {
  const [showBranchForm, setShowBranchForm] = useState(false)
  const [branchColumns, setBranchColumns] = useState([])
  const [isRevokeCase, setIsRevokeCase] = useState(false)

  const [, addBranchRequest] = useAddBranch()
  const [{ ADD_BRANCH_ERROR, addBranchStatus },
    dispatchError
  ] = useErrorContextValue()

  const { getProviderDetailData, getBranchListData, onGetBranchesRequest, providerCode } = props

  const [formDefaultValues, setFormDefaultValues] = useState({})

  const closeBranchForm = useCallback(() => {
    setFormDefaultValues({})
    setShowBranchForm(false)
  }, [])

  const handleAddBranch = useCallback(() => {
    setShowBranchForm(true)
  }, [])

  useEffect(() => {
    if (addBranchStatus && ADD_BRANCH_ERROR) {
      showNotification('error', addBranchStatus)
      dispatchError(resetError({
        addBranchStatus: ''
      }))
    } else if (addBranchStatus === 'success') {
      if (isRevokeCase) {
        setIsRevokeCase(false)
        showNotification('success', 'Access successfully Revoked')
      }
      onGetBranchesRequest({
        providerCode: providerCode,
        query: {
          is_active: [true, false]
        }
      })
      dispatchError(resetError({
        addBranchStatus: ''
      }))
    }
  }, [addBranchStatus, ADD_BRANCH_ERROR, dispatchError,
    isRevokeCase, onGetBranchesRequest, providerCode
  ])

  const handleAction = useCallback((useCase, data) => {
    switch (useCase) {
      case 'edit':
        setFormDefaultValues(data)
        setShowBranchForm(true)
        break
      case 'revoke':
        setIsRevokeCase(true)
        addBranchRequest({
          branchCode: data?.code,
          providerCode: providerCode,
          body: {
            code: data?.code,
            is_active: false
          }
        })
        break
      default:
        break
    }
  }, [addBranchRequest, providerCode])

  const getBranchListTable = useCallback(() => {
    return branchListTable({
      handleAction
    })
  }, [handleAction])

  useEffect(() => {
    setBranchColumns(getBranchListTable())
  }, [getBranchListTable])

  return (
    <LayoutContentStyle>
      {
      showBranchForm &&
        <Modal
          footer={null}
          visible={showBranchForm}
          onCancel={closeBranchForm}
        >
          <BranchForm
            defaultValues={formDefaultValues}
            onGetBranchesRequest={onGetBranchesRequest}
            onCloseBranchForm={closeBranchForm}
            providerCode={providerCode}
            extraDetails={getProviderDetailData?.extra_details?.branch_codes}
          />
        </Modal>
    }
      <Row type='flex' justify='space-between'>
        <Col>
          <h3 className='heading-blue'><b>Branch Locations</b></h3>
        </Col>
        <Col>
          <Button
            className='mb-10'
            type='primary'
            htmlType='submit'
            onClick={handleAddBranch}
          >
            ADD Location
          </Button>
        </Col>
      </Row>

      <div className='mt-10'>
        <TableWrapper
          columns={branchColumns}
          bordered
          rowKey={record => record.id}
          dataSource={getBranchListData?.length ? getBranchListData : []}
          pagination={{
            pageSize: 10
          }}
          className='isoSearchableTable agent-table-data'
        />
      </div>
    </LayoutContentStyle>
  )
}

ProviderBranches.propTypes = {
  getBranchListData: PropTypes.object,
  onGetBranchesRequest: PropTypes.func,
  providerCode: PropTypes.string
}

export default ProviderBranches
