import React, { useCallback, useEffect, useState } from 'react'
import { Select, InputNumber, Icon } from 'antd'
import { tieringCombinationOptions, tieringSelectOptions, vehicleData } from '../../constants'
import { TieringInputFieldsStyle } from './index.style'

const { Option } = Select

const TieringInputFields = ({ productType, formValues, setFormValues }) => {
  const [localValues, setLocalValues] = useState([{ rules: [{ param: '', gte: '', lt: '', source_type: '' }], rate: '', provider_level_rule_id: '' }])

  useEffect(() => {
    const newFormValues = []
    if (formValues !== '') {
      formValues.forEach((data, index) => {
        if (!('delete' in data)) {
          newFormValues.push(data)
        }
      })
      setLocalValues(newFormValues)
      setFormValues(() => newFormValues)
    }
  }, [formValues, setFormValues])

  const getSourceSelection = useCallback((index) => {
    if (productType === 'car-protection' && index === 0) {
      return [...tieringSelectOptions, ...tieringCombinationOptions]
    } else if (index === 0) {
      return tieringSelectOptions
    } else {
      return tieringCombinationOptions
    }
  }, [productType])

  const handleChange = (index, name, value, innerIndex) => {
    const newFormValues = [...localValues]
    if (name === 'source_type') {
      const newObj = getSourceSelection(innerIndex).filter((data) => data.source_type === value)[0]
      const param = 'param'
      newFormValues[index].rules[innerIndex][param] = newObj?.param
      newFormValues[index].rules[innerIndex][name] = newObj?.source_type
    } else if (name === 'rate') {
      newFormValues[index][name] = value
    } else if (name === 'val') {
      delete newFormValues[index].rules[innerIndex].gte
      delete newFormValues[index].rules[innerIndex].lt
      newFormValues[index].rules[innerIndex][name] = value
    } else {
      newFormValues[index].rules[innerIndex][name] = value
    }
    setLocalValues(newFormValues)
    setFormValues(newFormValues)
  }

  const addFormFields = () => {
    setLocalValues([...localValues, { rules: [{ param: '', gte: '', lt: '', source_type: '' }], rate: '' }])
  }

  const addInnerFormFields = (index) => {
    const newLocalValues = localValues.map((data, currIndex) => {
      if (currIndex === index) {
        data.rules = [
          ...data.rules,
          { param: '', gte: '', lt: '', source_type: '' }
        ]
      }
      return data
    })
    setLocalValues(newLocalValues)
  }
  const removeInnerFields = (index, innerIndex, ruleId) => {
    const newFormValues = [...localValues]
    newFormValues[index].rules.splice(innerIndex, 1)
    setLocalValues(newFormValues)
    setFormValues(newFormValues)
  }

  const removeFormFields = (index, ruleId) => {
    const newFormValues = [...localValues]
    newFormValues.splice(index, 1)
    newFormValues.push({
      delete: true,
      provider_level_rule_id: ruleId
    })
    setLocalValues(newFormValues)
    setFormValues(newFormValues)
  }

  return (
    <TieringInputFieldsStyle>
      {localValues.map((element, index) => (
        'rules' in element &&
          <div key={index} className='form-column'>
            <div className='form-fields'>
              {element.rules.map((innerElement, innerIndex) => (
                <div key='index' className='inner-form-fields'>
                  <Select
                    placeholder='Select Source'
                    id='source_type'
                    name='source_type'
                    onChange={e => handleChange(index, 'source_type', e, innerIndex)}
                    value={innerElement?.source_type ? innerElement?.source_type : 'Select Source '}
                    className='input-field-select'
                  >
                    {
                      getSourceSelection(innerIndex).map((data) => (
                        <Option key={data?.key} value={data.source_type}>{data?.source_type}</Option>
                      ))
                    }
                  </Select>
                  {
                    innerElement.source_type === 'Vehicle Type'
                      ? (
                        <Select
                          placeholder='Select Vehicle'
                          id='val'
                          name='val'
                          onChange={e => handleChange(index, 'val', e, innerIndex)}
                          value={innerElement?.val ? innerElement?.val : 'Select Vehicle '}
                          className='input-field-select'
                        >
                          {
                            vehicleData.map((data) => (
                              <Option key={data?.key} value={data.value}>{data?.value}</Option>
                            ))
                          }
                        </Select>
                        )
                      : (
                        <>
                          <InputNumber
                            name='gte'
                            value={innerElement.gte || ''}
                            className='input-field'
                            onChange={e => handleChange(index, 'gte', e, innerIndex)}
                            placeholder='Minimum Amount'
                          />
                          <InputNumber
                            name='lt'
                            value={innerElement.lt || ''}
                            className='input-field'
                            onChange={e => handleChange(index, 'lt', e, innerIndex)}
                            placeholder='Maximum Amount'
                          />
                        </>
                        )
                  }
                  {
                    innerIndex > 0
                      ? (
                        <button type='button' className='button-remove' onClick={() => removeInnerFields(index, innerIndex, element.provider_level_rule_id)}>
                          <Icon type='close-circle' className='close-circle-icon' />
                        </button>
                        )
                      : (
                        <button type='button' className='equalto'>
                          <span className='equalto'>=</span>
                        </button>
                        )
                  }
                </div>
              ))}
              <div>
                <button className='button-add' type='button' onClick={() => addInnerFormFields(index)}>Add more conditions</button>
              </div>
              <hr />
            </div>
            <div>
              <div className='form-field-ef'>
                <InputNumber
                  name='rate'
                  value={element.rate || ''}
                  className='input-field'
                  onChange={e => handleChange(index, 'rate', e)}
                  placeholder='Engineering Fee %'
                />
                {
                  index > 0 &&
                    <button type='button' className='button-remove' onClick={() => removeFormFields(index, element.provider_level_rule_id)}>
                      <Icon type='close-circle' className='close-circle-icon' />
                    </button>
                }
              </div>
            </div>
          </div>
      ))}
      <div className='button-add-field'>
        <button className='button-add' type='button' onClick={addFormFields}>+ Add new rule</button>
      </div>
    </TieringInputFieldsStyle>
  )
}

export default TieringInputFields
