
import { PRESET_ACTIONS } from './actions'
export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload } = action

  switch (type) {
    case PRESET_ACTIONS.GET_SHORT_PROVIDER_LIST:
    case PRESET_ACTIONS.GET_PRODUCT_LIST:
    case PRESET_ACTIONS.GET_INDEPENDENT_PACKAGE_LIST:
    case PRESET_ACTIONS.GET_PRESET_LIST:
    case PRESET_ACTIONS.GET_PRESET_DETAILS:
    case PRESET_ACTIONS.GET_EDIT_PRESET_DETAILS:
    case PRESET_ACTIONS.RESET_PRESET_STORE:
    case PRESET_ACTIONS.CREATE_PRESET:
    case PRESET_ACTIONS.UPDATE_PRESET:
    case PRESET_ACTIONS.DELETE_PRESET:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducer
