import React, { useCallback, useEffect, useState } from 'react'
import { Button, Col, Modal, Row } from 'antd'
import LayoutContentStyle from '../../../../../../../../components/utility/layoutContent.style'
import TableWrapper from '../../../../../pagination.style'
import IncomingCommissionForm from '../../../../components/IncomingCommissionForm'
import { CommissionListTable } from '../../../../constants'
import PropTypes from 'prop-types'
import get from 'lodash/get'
import { IncomingCommissionStyle } from './index.style'

function IncomingCommission (props) {
  const [showConfigForm, setShowConfigForm] = useState(false)
  const [configColumns, setConfigColumns] = useState([])
  const [isEditFormDisabled, setIsEditFormDisabled] = useState(false)
  const [showTieringOptions, setShowTieringOptions] = useState({ value: null, visible: false })
  const [disableFields, setDisableFields] = useState(false)

  const { getIncomingCommissionConfigListData, providerData } = props

  const [formDefaultValues, setFormDefaultValues] = useState({})

  const closeIncomingCommissionForm = useCallback(() => {
    setFormDefaultValues({})
    setShowConfigForm(false)
    setDisableFields(false)
  }, [])

  const handleAddBranch = useCallback(() => {
    setShowConfigForm(true)
    setIsEditFormDisabled(false)
  }, [])

  const handleAction = useCallback((useCase, data) => {
    setFormDefaultValues(data)
    if (useCase !== 'edit') {
      setIsEditFormDisabled(true)
      setDisableFields(false)
    } else {
      setIsEditFormDisabled(false)
      setDisableFields(true)
    }
    setShowConfigForm(true)
  }, [])

  const getCommissionListTable = useCallback(() => {
    return CommissionListTable({
      handleAction,
      setShowTieringOptions
    })
  }, [handleAction])

  useEffect(() => {
    setConfigColumns(getCommissionListTable())
  }, [getCommissionListTable])

  return (
    <LayoutContentStyle>
      {
        showConfigForm &&
          <Modal
            footer={null}
            visible={showConfigForm}
            onCancel={closeIncomingCommissionForm}
            className='commission-modal'
            width={1100}
          >
            <IncomingCommissionForm
              isEditFormDisabled={isEditFormDisabled}
              providerData={providerData}
              defaultValues={formDefaultValues}
              onCloseIncomingCommissionForm={closeIncomingCommissionForm}
              disableFields={disableFields}
            />
          </Modal>
      }
      <Row type='flex' justify='space-between'>
        <Col>
          <h3 className='heading-blue'><b>Incoming Commission Config</b></h3>
        </Col>
        <Col>
          <Button
            className='mb-10'
            type='primary'
            htmlType='submit'
            onClick={handleAddBranch}
          >
            Add New Config
          </Button>
        </Col>
      </Row>

      <div className='mt-10'>
        <TableWrapper
          columns={configColumns}
          bordered
          rowKey={record => record.id}
          dataSource={getIncomingCommissionConfigListData?.length ? getIncomingCommissionConfigListData : []}
          pagination={{
            pageSize: 10
          }}
          className='isoSearchableTable agent-table-data'
        />
      </div>
      {
        showTieringOptions.visible &&
          <Modal
            footer={null}
            visible={showTieringOptions}
            onCancel={() => setShowTieringOptions({ value: null, visible: false })}
            className='commission-modal'
          >
            <IncomingCommissionStyle>
              {
            showTieringOptions.value?.map((data, index) => {
              return (
                <React.Fragment key={index}>
                  <div key={index} className='outer-row'>
                    <div className='tiering-row'>
                      {
                      data?.rules?.map((innerData, key) => {
                        return (
                          <div className='inner-row' key={key}>
                            <div className='tiering-readonly-first'>{get(innerData, 'source_type', '') || 'N/A'}</div>
                            {
                              get(innerData, 'source_type', '') === 'Vehicle Type'
                                ? <div className='tiering-readonly'>{innerData?.val || 'N/A'}</div>
                                : (
                                  <>
                                    <div className='tiering-readonly'>{innerData?.val.split('-')[0]}</div>
                                    upto
                                    <div className='tiering-readonly'>{innerData?.val?.split('-')[1] || 'N/A'}</div>
                                  </>)
                            }
                          </div>
                        )
                      })
                    }
                    </div>
                    <div className='fee'>
                      =
                      <div className='tiering-readonly'>{get(data, 'rate', '') || 'N/A'}%</div>
                    </div>
                  </div>
                  <hr />
                </React.Fragment>
              )
            })
          }
            </IncomingCommissionStyle>
          </Modal>
      }
    </LayoutContentStyle>
  )
}

IncomingCommission.propTypes = {
  providerCode: PropTypes.string,
  getIncomingCommissionConfigListData: PropTypes.object
}

export default IncomingCommission
