import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Form, Row, Checkbox } from 'antd'
import { isEmpty } from 'lodash'
import { useCallback, useEffect, useState } from 'react'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import { showNotification } from '../../../../../../components/ShowNotification'
import { useAddUser } from '../../state/hooks/useProviderState'
import { UserFormStyle } from './index.style'
import PropTypes from 'prop-types'
import get from 'lodash/get'
import { isVNPath } from '../../../../../../helpers/utility'

const CheckboxGroup = Checkbox.Group

function UserForm (props) {
  const { providerCode, onfetchUserList, onCloseUserForm, defaultValues = {} } = props
  const [checkAll, setCheckAll] = useState(get(defaultValues, 'provider_branch_list', []).includes('ALL'))
  const [branchErr, setBranchErr] = useState('')

  const [checkedList, setCheckedList] = useState(
    get(defaultValues, 'provider_branch_list', []).includes('ALL')
      ? props.branches.map((branch) => branch.code)
      : get(defaultValues, 'provider_branch_list', []).filter(branch => branch !== 'ALL')
  )
  const [branchList, setBranchList] = useState(props.branches.map((branch) => (
    {
      label: branch.name,
      value: branch.code
    })
  ))

  const [, addUserRequest] = useAddUser()

  const [{ ADD_USER_ERROR, addUserStatus },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    setBranchList(props.branches.map((branch) => (
      {
        label: branch.name,
        value: branch.code
      })
    ))
  }, [props.branches])

  useEffect(() => {
    if (addUserStatus === 'success') {
      if (!isEmpty(defaultValues)) {
        showNotification('success', 'User successfully Edited')
      } else {
        showNotification('success', 'A new user is successfully added')
      }
      onfetchUserList()
      onCloseUserForm()
      dispatchError(resetError({
        addUserStatus: ''
      }))
    } else if (ADD_USER_ERROR && addUserStatus) {
      showNotification('error', addUserStatus)
      dispatchError(resetError({
        addUserStatus: ''
      }))
    }
  }, [addUserStatus, ADD_USER_ERROR, defaultValues,
    dispatchError, onCloseUserForm, onfetchUserList
  ])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    props.form.validateFields(async (err, values) => {
      if (!err) {
        const providerBranchList = checkAll ? ['ALL'] : checkedList
        if (providerBranchList.length === 0) {
          setBranchErr('Please select atleast one option')
          return
        }
        if (isVNPath()) {
          const phone = values.phone
          values.phone = `84-${phone}`
        }
        addUserRequest({
          id: get(defaultValues, 'reference_id', ''),
          body: {
            agent_provider: providerCode,
            provider_branch_list: providerBranchList,
            ...values
          }
        })
      }
    })
  }, [props, checkedList, addUserRequest,
    defaultValues, providerCode, checkAll
  ])

  const renderFormItems = useCallback((item) => {
    // wrapping utitily function with class function to pass common parameters
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: props.form.getFieldDecorator,
      getFieldValue: props.form.getFieldValue
    })
  }, [props.form])

  const renderForm = useCallback((formData) => {
    return (
      formData.map((item, index) => (
        <div key={index}>
          {
            renderFormItems(item)
          }
        </div>
      ))
    )
  }, [renderFormItems])

  const handleCheckAllChange = useCallback((e) => {
    setBranchErr('')
    setCheckedList(e.target.checked ? branchList.map((b) => b.value) : [])
    setCheckAll(e.target.checked)
  }, [branchList])

  const handleCheckChange = useCallback((checkedList) => {
    setBranchErr('')
    setCheckedList(checkedList)
    setCheckAll(checkedList.length === branchList.length)
  }, [branchList])

  const renderBranches = useCallback(() => {
    return (
      <div>
        <div><span className='color-red'>*</span> Branch Permission:</div>
        <div className='color-red'>
          {branchErr}
        </div>
        <Checkbox
          onChange={handleCheckAllChange}
          checked={checkAll}
        >
          Select all
        </Checkbox>
        <CheckboxGroup
          options={branchList}
          value={checkedList}
          onChange={handleCheckChange}
        />
      </div>
    )
  }, [branchList, checkedList, checkAll,
    handleCheckAllChange, handleCheckChange,
    branchErr
  ])

  const getDefaultPhone = useCallback(() => {
    const phone = get(defaultValues, 'phone', '')
    if (phone) {
      const val = `${phone}`.split('-')
      if (val.length === 2) {
        return val[1]
      } else {
        return val[0]
      }
    }
    return phone
  }, [defaultValues])

  return (
    <UserFormStyle>
      <Form onSubmit={handleSubmit}>
        {
          renderForm([
            {
              name: 'email',
              title: 'Email',
              subTitle: 'email',
              type: 'email',
              defaultValue: get(defaultValues, 'email', '')
            },
            {
              name: 'name',
              title: 'Name',
              subTitle: 'name',
              type: 'text',
              defaultValue: get(defaultValues, 'name', '')
            },
            {
              name: 'phone',
              title: 'Phone',
              subTitle: 'phone',
              type: 'number',
              defaultValue: getDefaultPhone()
            }
          ])
        }
        {
          renderBranches()
        }
        <Row justify='end' type='flex'>
          <Button type='primary' htmlType='submit'>
            Submit
          </Button>
        </Row>
      </Form>
    </UserFormStyle>
  )
}

UserForm.propTypes = {
  providerCode: PropTypes.string,
  onfetchUserList: PropTypes.func,
  onCloseUserForm: PropTypes.func,
  defaultValues: PropTypes.object,
  branches: PropTypes.arrayOf(PropTypes.object)
}

const wrapperUserForm = Form.create()(UserForm)

export default wrapperUserForm
