import { Button, Col, Row } from 'antd'
import { compareStringDescending, presetListTable } from '../../helpers/constants'
import TableWrapper from '../../../Agent/pagination.style'
import { useHistory } from 'react-router'
import { useMemo } from 'react'
import PropTypes from 'prop-types'
import { get } from 'lodash'
import { createPresetRoute } from '../../config/urls'

function PresetList (props) {
  const { providerCode, loading } = props
  const data = get(props, 'data', [])
  const history = useHistory()

  const sortedData = useMemo(() => {
    const d = [...data]
    d.sort(compareStringDescending)
    return d
  }, [data])

  const addPresetPath = useMemo(() => {
    return createPresetRoute({ providerCode })
  }, [providerCode])

  return (
    <>
      <Row type='flex' justify='space-between'>
        <Col>
          {providerCode && <h3 className='heading-blue'><b>Coverage Preset</b></h3>}
        </Col>
        <Col>
          <Button
            className='mb-10'
            type='primary'
            onClick={() => history.push(addPresetPath)}
          >
            ADD Preset
          </Button>
        </Col>
      </Row>
      <div className='mt-10'>
        <TableWrapper
          columns={presetListTable(history, providerCode)}
          bordered
          rowKey={record => record.id}
          dataSource={providerCode ? sortedData.filter(x => x.provider.code === providerCode) : sortedData}
          loading={loading}
          className='isoSearchableTable agent-table-data'
        />
      </div>
    </>
  )
}

PresetList.propTypes = {
  providerCode: PropTypes.string,
  loading: PropTypes.bool
}

export default PresetList
