import { Button, Col, Modal, Row } from 'antd'
import get from 'lodash/get'
import { useCallback, useMemo, useState } from 'react'
import LayoutContentStyle from '../../../../../../../../components/utility/layoutContent.style'
import ProviderForm from '../../../../components/ProviderForm/'
import PropTypes from 'prop-types'
import moment from 'moment-timezone'
import Cookies from 'universal-cookie'
const cookies = new Cookies()

function ProviderInfo (props) {
  const userTimeZone = useMemo(() => {
    return cookies.get('userProfile').user_timezone
  }, [])

  const [showProviderForm, setShowProviderForm] = useState(false)
  const { providerInfo, onGetProviderDetail } = props
  const renderInfo = useCallback(() => {
    const data = [
      [
        {
          key: 'Provider Name',
          value: get(providerInfo, 'name', '')
        },
        {
          key: 'Provider Code',
          value: get(providerInfo, 'code', '')
        }
      ],
      [
        {
          key: 'Email',
          value: get(providerInfo, 'email', '')
        },
        {
          key: 'Created At',
          value: moment(get(providerInfo, 'created_at', '')).tz(userTimeZone).format('DD-MM-YYYY')
        }
      ],
      [
        {
          key: 'Email for claims',
          value: get(providerInfo, 'headquarter_branch.claims_email', '')
        },
        {
          key: 'Contact Center',
          value: get(providerInfo, 'headquarter_branch.claims_contact_no', '')
        }
      ],
      [
        {
          key: 'City',
          value: get(providerInfo, 'headquarter_branch.location.city_name', '')
        },
        {
          key: 'Province',
          value: get(providerInfo, 'headquarter_branch.location.province_name', '')
        }
      ],
      [
        {
          key: 'Address',
          value: get(providerInfo, 'headquarter_branch.location.address', '')
        },
        {
          key: 'Zip Code',
          value: get(providerInfo, 'headquarter_branch.location.postal_code', '')
        }
      ],
      [
        {
          key: 'Status',
          value: get(providerInfo, 'headquarter_branch.is_active', '') ? 'Active' : 'Inactive'
        },
        {
          key: 'logo',
          value: get(providerInfo, 'logo_url', ''),
          img: true
        }
      ]
    ]

    return (
      <>
        {
          data.map((row, i) => (
            <Row key={i} type='flex' justify='space-between'>
              <Col span={12}>
                <Row type='flex'>
                  <Col span={8}>
                    <b>{row[0]?.key}</b>
                  </Col>
                  <Col span={14}>
                    {
                      (row[0]?.img)
                        ? <img src={row[0]?.value} height='50px' alt='' />
                        : row[0]?.value
                    }
                  </Col>
                </Row>
              </Col>
              {
                row?.[1] &&
                  <Col span={12}>
                    <Row type='flex'>
                      <Col span={8}>
                        <b>{row[1]?.key}</b>
                      </Col>
                      <Col span={14}>
                        {
                        (row[1]?.img)
                          ? <img src={row[1]?.value} height='50px' alt='' />
                          : row[1]?.value
                      }
                      </Col>
                    </Row>
                  </Col>
              }
            </Row>
          ))
        }
      </>
    )
  }, [providerInfo, userTimeZone])

  const closeProviderForm = useCallback(() => {
    setShowProviderForm(false)
  }, [])

  const handleEditProvider = useCallback(() => {
    setShowProviderForm(true)
  }, [])

  return (
    <LayoutContentStyle>
      {
        showProviderForm &&
          <Modal
            style={{ top: '0' }}
            footer={null}
            visible={showProviderForm}
            onCancel={closeProviderForm}
          >
            <ProviderForm onGetProviderDetail={onGetProviderDetail} defaultValues={providerInfo} onCloseProviderForm={closeProviderForm} />
          </Modal>
      }
      <Row type='flex' justify='space-between'>
        <Col>
          <h3 className='heading-blue'><b>Providers Details</b></h3>
        </Col>
        <Col>
          <Button
            className='mb-10'
            type='primary'
            htmlType='submit'
            onClick={handleEditProvider}
          >
            Edit
          </Button>
        </Col>
      </Row>

      <div className='mt-10'>
        {
          renderInfo()
        }
      </div>
    </LayoutContentStyle>
  )
}

ProviderInfo.propTypes = {
  providerInfo: PropTypes.object,
  onGetProviderDetail: PropTypes.func
}

export default ProviderInfo
